def two_sum_sorted(a, target):
    i, j = 0, len(a) - 1
    while i < j:
        s = a[i] + a[j]
        if s == target:
            return (i, j)
        if s < target:
            i += 1
        else:
            j -= 1
    return None

def build(a):
    p = [0]
    for x in a:
        p.append(p[-1] + x)
    return p

def range_sum(p, l, r):
    return p[r + 1] - p[l]

def is_anagram(s, t):
    from collections import Counter
    return Counter(s) == Counter(t)

def count_pairs(a, k):
    seen, ans = {}, 0
    for x in a:
        ans += seen.get(x - k, 0) + seen.get(x + k, 0)
        seen[x] = seen.get(x, 0) + 1
    return ans // (1 if k else 2)

def has_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False

def merge(iv):
    iv.sort()
    out = []
    for s, e in iv:
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

def smallest_feasible(lo, hi, feasible):
    # feasible(lo) False, feasible(hi) True
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid
    return hi

def next_greater(a):
    ans, st = [-1] * len(a), []
    for i, x in enumerate(a):
        while st and a[st[-1]] < x:
            ans[st.pop()] = x
        st.append(i)
    return ans

def max_activities(iv):
    iv.sort(key=lambda p: p[1])
    count, end = 0, float('-inf')
    for s, e in iv:
        if s >= end:
            count, end = count + 1, e
    return count

def tsp(dist):
    n = len(dist)
    INF = float('inf')
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1][0] = 0
    for mask in range(1 << n):
        for u in range(n):
            if not mask & (1 << u):
                continue
            for v in range(n):
                if mask & (1 << v):
                    continue
                dp[mask | (1 << v)][v] = min(dp[mask | (1 << v)][v], dp[mask][u] + dist[u][v])
    return min(dp[(1 << n) - 1][u] + dist[u][0] for u in range(n))

def knapsack(wt, val, W):
    dp = [0] * (W + 1)
    for w, v in zip(wt, val):
        for c in range(W, w - 1, -1):  # descending = 0/1
            dp[c] = max(dp[c], dp[c - w] + v)
    return dp[W]

PSEUDOCODE count_upto(s):   # s = decimal string of X
  memo = {}
  def dfs(i, tight, started, sum):
    if i == len(s): return sum
    key = (i, tight, started, sum)
    if key in memo and not tight: return memo[key]
    limit = int(s[i]) if tight else 9
    ans = 0
    for d in 0..limit:
      ans += dfs(i+1, tight and d == limit, started or d > 0, sum + (d if started or d > 0 else 0))
    if not tight: memo[key] = ans
    return ans
  return dfs(0, True, False, 0)
